 $('app').innerHTML=`<header class="row between">${brand()}${account?.role&&account.role!=='admin'?globalPatientSearch():''}<div class="row">${themeControl()}<span class="pill">${esc(account.label)} · ${esc(account.username)}</span>${button('Κλείδωμα','lock','','secondary')}${button('Αποσύνδεση','logout','','secondary')}</div></header><div class="shell"><aside class="sidebar"><nav aria-label="Κύρια πλοήγηση">${menu.map(([id,t])=>button(navIcon(id)+'<span>'+t+'</span>',id==='visit'?'newVisit':'nav',id==='visit'?'':id,page===id?'active':'')).join('')}${button(navIcon('help')+'<span>Βοήθεια</span>','help','','help')}</nav></aside><main class="screen-${page}"><div class="workspace-title row between"><div><div class="eyebrow">${version}</div><div class="workspace-heading">${navIcon(page)}<h1>${titles[page]}</h1></div></div><span class="pill">${displayDate(today())}</span></div>${notice()}${recoveryNotice()}${loadError?`<div class="error">${esc(loadError)}</div>${button('Εξαγωγή ακατέργαστων δεδομένων','rawBackup')}`:({home,prescription:prescriptionPage,reports:reportsPage,workspaces:workspacesPage,directory:directoryPage,patients:patientsPage,record:recordPage,clinical:clinicalPage,examinations:examinationsPage,examReport:examResultsReport,imaging:imagingPage,aiDesign:aiDesignPage,historyReport:historyReportPage,visit:visitPage,visitStart:visitStartPage,calendar:calendarPage,report:reportPage,settings:settingsPage,admin:adminPage,statistics:statisticsPage,feedback:feedbackPage,program:programPage}[page])()}</main></div>${footer()}`;
 mountPhotographicFrame();
 const workspace=document.querySelector('#app .shell>main');if(workspace&&!workspace.classList.contains('literal-interior')){workspace.classList.add('workspace-standard');prepareStandardPanels(workspace);}
