document.addEventListener('input',e=>{if(e.target.id==='directorySearch'){directoryQuery=e.target.value;$('directoryResults').innerHTML=directoryRows();}if(e.target.id==='search'){patientQuery=e.target.value;patientPage=1;refreshPatientResults();}if(e.target.id==='globalPatientSearch')$('globalPatientHits').innerHTML=globalPatientHits(e.target.value);if(e.target.id==='historyPatientSearch'){$('historyPatientResults').innerHTML=historyPatientResults(e.target.value);}});
function historyPatientResults(query){const q=query.trim();if(!q)return '';if(!/^[0-9]+$/.test(q)&&q.length<2)return '<p class="muted">Γράψτε τουλάχιστον 2 γράμματα επιθέτου.</p>';const list=state.patients.filter(p=>matchesPatient(p,q,{history:true}));return list.length?`<p>${list.length} αποτελέσματα · επιλέξτε τον σωστό φάκελο:</p><div class="patient-matches">${list.map(p=>button(`${esc(p.name)} · ${p.age} ετών · Α.Μ.Κ.Α.: ${esc(p.amka)||'—'}`,'record',p.id,'secondary')).join('')}</div>`:'<p>Δεν βρέθηκαν ασθενείς.</p>';}

document.addEventListener('change',async e=>{try{
 if(e.target.dataset.patientSelect){if(e.target.checked)selectedPatientIds.add(e.target.dataset.patientSelect);else selectedPatientIds.delete(e.target.dataset.patientSelect);refreshPatientResults();}
 if(e.target.id==='selectPatientPage'){for(const p of paginatedPatients()){if(e.target.checked)selectedPatientIds.add(p.id);else selectedPatientIds.delete(p.id);}refreshPatientResults();}
 if(['patientStatusFilter','patientClinicFilter','patientFavFilter','patientPageSize','patientLastFrom','patientLastTo'].includes(e.target.id)){const from=dateFilterValue($('patientLastFrom').value),to=dateFilterValue($('patientLastTo').value);if(from===null||to===null||from&&to&&from>to)throw Error('Ελέγξτε το διάστημα τελευταίας επίσκεψης.');patientStatusFilter=$('patientStatusFilter').value;patientClinicFilter=$('patientClinicFilter').value;patientFavFilter=$('patientFavFilter').value;patientPageSize=Number($('patientPageSize').value);patientLastFrom=from;patientLastTo=to;patientPage=1;refreshPatientResults();}
 if(e.target.id==='summaryPatient'){const id=e.target.value;if(!flush()){e.target.value=selectedPatient;return;}selectedPatient=id;render();}
 if(e.target.id==='imagingPatient'){const value=e.target.value;if(!flush()){e.target.value=selectedPatient;return;}selectedPatient=value;imagingExam='';imagingCompare='';imagingFile='';imageZoom=1;render();}
 if(e.target.id==='imageFileSelect'){const value=e.target.value;if(!flush()){e.target.value=imagingFile;return;}imagingFile=value;imageZoom=1;render();}
 if(e.target.id==='compareImageExam'){const value=e.target.value;if(!flush()){e.target.value=imagingCompare;return;}imagingCompare=value;render();}
 if(e.target.id==='imagingType'){const value=e.target.value;if(!flush()){e.target.value=imagingType;return;}imagingType=value;imagingExam='';imagingCompare='';imagingFile='';render();}
 if(['clinicalPatient','examPatient'].includes(e.target.id)){const id=e.target.value;if(!flush()){e.target.value=selectedPatient;return;}selectedPatient=id;editingExamination='';render();}
 if(e.target.id==='examTypeFilter'){if(!flush())return;examCategory=e.target.value;editingExamination='';render();}
 if(e.target.dataset.module){if(account?.role!=='admin')throw Error('Απαιτείται ADMIN.');const id=e.target.dataset.module;if(!Object.hasOwn(MODULES,id))return;const desired=e.target.checked;update(s=>s.settings.modules[id]=desired);toast('Η διαθεσιμότητα της ενότητας ενημερώθηκε. Τα δεδομένα διατηρήθηκαν.');}
 if(['programDate','programClinic'].includes(e.target.id)){programDate=isoDate($('programDate').value);programClinic=$('programClinic').value;if(!programDate)throw Error('Ελέγξτε την ημερομηνία.');$('programDocument').innerHTML=programDocument();}
 if(e.target.id==='themePicker'){const value=e.target.value;if(!['dark','light','system'].includes(value))return;localStorage.setItem(THEME_KEY,value);theme=value;applyTheme();}
 if(e.target.id==='recordPatient'){selectedPatient=e.target.value;recordQuery='';historyType='';render();}
 if(e.target.id==='visitReasonPreset'&&e.target.value){if(!$('visit_reason').value||confirm('Να αντικατασταθεί ο λόγος επίσκεψης;')){$('visit_reason').value=e.target.value;$('visit_reason').dispatchEvent(new Event('input',{bubbles:true}));}}
 if(['filterDate','filterClinic','filterStatus'].includes(e.target.id))filterAppointments();
 if(e.target.id==='hospitalToggle'){if(account?.role!=='admin')throw Error('Απαιτείται δοκιμαστικός ADMIN.');const enabled=e.target.checked;if(!enabled&&state.appointments.some(a=>a.clinic==='hospital'&&a.status==='scheduled'&&a.date>=today()))throw Error('Υπάρχουν μελλοντικά ραντεβού Νοσοκομείου. Μεταφέρετε ή ακυρώστε τα πριν την απενεργοποίηση.');update(s=>s.settings.hospital=enabled);if(!enabled&&activeClinic==='hospital')activeClinic='clinic-1';toast('Η ρύθμιση αποθηκεύτηκε. Το ιστορικό διατηρήθηκε.');}
 if(e.target.id==='backupFile'&&e.target.files[0]){if(account.role==='reception')throw Error('Δεν επιτρέπεται επαναφορά.');const file=e.target.files[0];if(file.size>150*1024*1024)throw Error('Το αντίγραφο υπερβαίνει τα 150 MB.');const parsed=JSON.parse(await file.text());const encoded=parsed.attachmentFiles||[];delete parsed.attachmentFiles;const candidate=normalize(parsed);const restoredFiles=decodeFiles(candidate.examinations,encoded);if(!confirm(`Επαναφορά ${candidate.patients.length} ασθενών, ${candidate.visits.length} επισκέψεων και ${candidate.appointments.length} ραντεβού; Αντικαθιστά τις τωρινές δοκιμές. Εξάγετε πρώτα BACKUP αν θέλετε να τις κρατήσετε.`))return;const added=[];try{for(const f of restoredFiles){const existing=await getFile(f.id);if(existing){if(existing.size!==f.blob.size||await blobFingerprint(existing)!==await blobFingerprint(f.blob))throw Error('Υπάρχει διαφορετικό τοπικό αρχείο με τον ίδιο κωδικό.');}else{await putFile(f.id,f.blob);added.push(f.id);}}commit(candidate);}catch(err){for(const id of added)await deleteFile(id);throw err;}clearRecovery();selectedPatientIds.clear();showPatientForm=false;editingPatient='';clinicalTab='overview';selectedPatient='';editingVisit='';editingAppointment='';page='home';render();toast('Το αντίγραφο επαναφέρθηκε.');}
 }catch(err){if(e.target.id==='hospitalToggle')e.target.checked=state.settings.hospital;if(e.target.dataset.module)e.target.checked=enabled(e.target.dataset.module);error(err.message);}});
$('closeHelp').addEventListener('click',()=>$('help').close());
['pointerdown','keydown','input','scroll'].forEach(type=>document.addEventListener(type,()=>lastActivity=Date.now(),{passive:true}));
setInterval(()=>{if(account&&Date.now()-lastActivity>=300000){captureRecovery();try{if(page==='visit')persistVisit();}catch{}account=null;page='login';$('help').close();render();toast('Το περιβάλλον κλειδώθηκε μετά από 5 λεπτά αδράνειας. Η διακοπείσα φόρμα μπορεί να ανακτηθεί μετά την είσοδο.');}},10000);
window.addEventListener('beforeunload',e=>{if(['visit','patients','clinical','examinations','imaging','summaryNotes','prescription'].includes(page)&&account){try{if(!flush()){e.preventDefault();e.returnValue='';}}catch{e.preventDefault();e.returnValue='';}}});
