function prepareStandardPanels(main){
 const form=main.querySelector('#examForm');if(!form)return;
 const metadata=form.querySelector(':scope>.grid'),results=form.querySelector(':scope>.split'),notes=form.querySelector('#examNotes')?.closest('label'),fileLabel=form.querySelector('#examFiles')?.closest('label'),hint=form.querySelector('.field-hint'),remove=[...form.querySelectorAll('label')].filter(n=>n.querySelector('[data-remove-file]')),error=form.querySelector('#formError'),submit=form.querySelector('button[type=submit]');
 if(!metadata||!results||!notes||!fileLabel||!submit)return;
 const section=(title,kind,nodes)=>{const box=document.createElement('section');box.className='workspace-subpanel '+kind;const h=document.createElement('h3');h.textContent=title;box.append(h,...nodes.filter(Boolean));return box;};
 const meta=section('Στοιχεία εξέτασης','exam-metadata',[metadata]),clinical=section('Αποτελέσματα και παρατηρήσεις','exam-clinical',[results,notes]),files=section('Έγγραφα και αρχεία','exam-attachments',[fileLabel,hint,...remove]);const footer=document.createElement('div');footer.className='workspace-form-footer';if(error)footer.append(error);footer.append(submit);form.replaceChildren(meta,clinical,files,footer);form.classList.add('exam-editor-grid');
}

document.addEventListener('change',e=>{if(e.target.id==='examOverviewCategory'){examCategory=e.target.value;render();}if(e.target.id==='examPeriod'){examPeriod=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='examOverviewSearch'){const n=e.target.selectionStart;examOverviewQuery=e.target.value;render();const el=$('examOverviewSearch');if(el){el.focus();el.setSelectionRange(n,n);}}});
function examCutoff(){if(examPeriod==='all')return '';const d=new Date(today()+'T12:00:00Z');d.setUTCFullYear(d.getUTCFullYear()-Number(examPeriod));return d.toISOString().slice(0,10);}
function periodExams(){const cutoff=examCutoff();return (state.examinations||[]).filter(e=>e.patientId===selectedPatient&&(!cutoff||e.date>=cutoff)).sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id));}
function overviewExams(){const query=searchText(examOverviewQuery);return periodExams().filter(e=>(!examCategory||e.category===examCategory)&&(!query||searchText([e.title,EXAM_TYPES[e.category],e.result,e.notes,...e.files.map(f=>f.name)].join(' ')).includes(query)));}
function overviewSelection(){const rows=overviewExams();const selected=rows.find(e=>e.id===selectedExamResult)||rows[0];selectedExamResult=selected?.id||'';return selected;}
function examCategoryNavigation(){const all=(state.examinations||[]).filter(e=>e.patientId===selectedPatient);return `<h3>Κατηγορίες</h3>${[['','Όλες οι εξετάσεις'],...Object.entries(EXAM_TYPES)].map(([id,label])=>button(`${esc(label)} <span>${all.filter(e=>!id||e.category===id).length}</span>`,'examQuickCategory',id,examCategory===id?'active':'secondary')).join('')}`;}
function examOverviewControls(){return `<div class="row between"><h3>Ιστορικό εξετάσεων · ${overviewExams().length}</h3>${select('Κατηγορία','examOverviewCategory',[['','Όλες οι κατηγορίες'],...Object.entries(EXAM_TYPES)],examCategory)}${select('Περίοδος','examPeriod',[['all','Όλες οι ημερομηνίες'],['3','Τελευταία 3 έτη'],['5','Τελευταία 5 έτη']],examPeriod)}</div>${field('Αναζήτηση εξέτασης / αποτελέσματος','examOverviewSearch',examOverviewQuery,'search','autocomplete="off" placeholder="Αναζήτηση εξέτασης, αποτελέσματος ή αρχείου…"')}`;}
function examResultTable(){const chosen=overviewSelection();return `<div class="exam-overview-table"><table><thead><tr><th>Ημερομηνία</th><th>Εξέταση</th><th>Κατηγορία</th><th>Αποτέλεσμα</th><th>Τιμές αναφοράς</th><th>Ενέργειες</th></tr></thead><tbody>${overviewExams().map(e=>`<tr class="${e.id===chosen?.id?'selected':''}"><td>${displayDate(e.date)}</td><td><button type="button" class="exam-result-title" data-action="selectExamResult" data-id="${esc(e.id)}">${esc(e.title)}</button></td><td>${esc(EXAM_TYPES[e.category])}</td><td class="prewrap">${esc(e.result)||'—'}</td><td>${esc(e.referenceRange)||'—'}</td><td>${button('Προβολή','selectExamResult',e.id,'secondary')}${button('Επεξεργασία','editExam',e.id,'secondary')}</td></tr>`).join('')||'<tr><td colspan="6">Δεν υπάρχουν εξετάσεις με αυτά τα φίλτρα.</td></tr>'}</tbody></table></div>`;}
function examResultDetails(){const e=overviewSelection();return `<h3>Λεπτομέρειες εξέτασης</h3>${e?`<strong>${esc(e.title)}</strong><p>${displayDate(e.date)} · ${esc(EXAM_TYPES[e.category])}</p><p class="prewrap"><b>Αποτέλεσμα:</b> ${esc(e.result)||'Δεν έχει καταγραφεί.'}</p><p class="prewrap"><b>Τιμές αναφοράς:</b> ${esc(e.referenceRange)||'Δεν έχουν καταγραφεί.'}</p><p class="prewrap">${esc(e.notes)}</p><div class="row">${button('Επεξεργασία','editExam',e.id,'secondary')}${button('Διαγραφή δοκιμαστικής εξέτασης','removeExam',e.id,'danger')}</div>`:'<p>Επιλέξτε ή προσθέστε εξέταση για τον συγκεκριμένο ασθενή.</p>'}`;}
function examImagingLinks(){const rows=periodExams().filter(e=>imagingTypes.includes(e.category));return `<h3>Απεικονιστικές εξετάσεις</h3>${rows.slice(0,5).map(e=>`<article class="exam-image-link">${navIcon('imaging')}<div><strong>${esc(e.title)}</strong><small>${displayDate(e.date)} · ${e.files.length} αρχεία</small>${button('Προβολή / ευρήματα','openImaging',e.id,'secondary')}</div></article>`).join('')||'<p>Δεν υπάρχουν αποθηκευμένες απεικονίσεις στην επιλεγμένη περίοδο.</p>'}${button('Όλες οι απεικονίσεις','openImaging',selectedPatient,'secondary')}`;}
function examPsaPanel(){const ids=new Set(periodExams().map(e=>e.id));return `<h3>Εξέλιξη PSA</h3>${psaChart(selectedPatient,ids)}`;}
function examPsaComparison(){const ids=new Set(periodExams().map(e=>e.id)),values=psaValues(state,selectedPatient).filter(v=>ids.has(v.id));const last=values.at(-1),previous=values.at(-2);return `<h3>Σύγκριση τελευταίων τιμών PSA</h3>${last&&previous?`<div class="exam-comparison-values"><span>${displayDate(previous.date)}<b>${previous.value.toLocaleString('el-GR')} ng/mL</b></span><span>${displayDate(last.date)}<b>${last.value.toLocaleString('el-GR')} ng/mL</b></span></div><p>Διαφορά: ${(last.value-previous.value).toLocaleString('el-GR',{maximumFractionDigits:2})} ng/mL</p><small>Αριθμητική σύγκριση, χωρίς κλινική αξιολόγηση.</small>`:'<p>Χρειάζονται δύο αριθμητικές τιμές με μονάδα ng/mL.</p>'}`;}
function examDocumentList(){const files=periodExams().flatMap(e=>e.files.map(f=>({...f,date:e.date})));return `<h3>Έγγραφα εξετάσεων</h3>${files.map(f=>`<div class="exam-document-row"><span>${esc(f.name)}<small>${displayDate(f.date)} · ${(f.size/1024).toFixed(1)} KB</small></span>${button('Λήψη','downloadExam',f.id,'secondary')}</div>`).join('')||'<p>Δεν υπάρχουν επισυναπτόμενα αρχεία στην επιλεγμένη περίοδο.</p>'}${button('Προσθήκη εξέτασης / αρχείων','newExam','','secondary')}`;}
function examResultsReport(){const p=patient(selectedPatient);if(!p)return '<p>Επιλέξτε ασθενή.</p>';const rows=overviewExams();return `<div class="actions row">${button('PRINT · Εκτύπωση / PDF','print')}${button('Επιστροφή στις εξετάσεις','nav','examinations','secondary')}</div><article class="report" id="examReportDocument"><h2>UroMed Nexus Suite</h2><h3>Δοκιμαστική αναφορά αποτελεσμάτων εξετάσεων</h3><div class="notice">Μόνο φανταστικά στοιχεία · Δεν αποτελεί ιατρική γνωμάτευση.</div><p><b>${esc(p.name)}</b><br>Α.Μ.Κ.Α.: ${esc(p.amka)||'—'} · ${p.age} ετών</p><p>${rows.length} εξετάσεις με τα επιλεγμένα φίλτρα · ${examCutoff()?displayDate(examCutoff())+' έως σήμερα':'Όλες οι ημερομηνίες'}</p>${rows.map(e=>`<section><h3>${displayDate(e.date)} · ${esc(e.title)}</h3><p><b>Κατηγορία:</b> ${esc(EXAM_TYPES[e.category])}</p><p class="prewrap"><b>Αποτέλεσμα:</b> ${esc(e.result)||'—'}</p><p class="prewrap"><b>Τιμές αναφοράς:</b> ${esc(e.referenceRange)||'—'}</p><p class="prewrap">${esc(e.notes)}</p>${e.files.length?`<p>Αρχεία: ${e.files.map(f=>esc(f.name)).join(', ')}</p>`:''}</section>`).join('')||'<p>Δεν υπάρχουν εξετάσεις με αυτά τα φίλτρα.</p>'}<footer>${version} · Εκπαιδευτική δοκιμαστική αναφορά</footer></article>`;}

function directoryRows(){const q=searchText(directoryQuery.trim()),digits=v=>String(v||'').replace(/[^0-9+]/g,'');const rows=[...state.patients].filter(p=>!q||[p.lastName,p.firstName,p.name,p.amka,p.phone,p.phone2,p.email].some(v=>searchText(v||'').includes(q))||(/[0-9]/.test(q)&&[p.phone,p.phone2].some(v=>digits(v).includes(digits(q))&&digits(q)))).sort((a,b)=>(a.lastName||a.name).localeCompare(b.lastName||b.name,'el'));const phone=v=>v?`<a class="directory-contact" href="tel:${esc(digits(v))}">${esc(v)}</a>`:'—';return `<p class="field-hint">${rows.length} από ${state.patients.length} ασθενείς · Τα στοιχεία ενημερώνονται από την ίδια εγγραφή ασθενούς.</p><div class="table-wrap"><table class="directory-table"><thead><tr><th>Επίθετο</th><th>Όνομα</th><th>Α.Μ.Κ.Α.</th><th>Τηλέφωνο</th><th>Δεύτερο τηλέφωνο</th><th>E-mail</th><th>Ενέργειες</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.lastName||p.name)}${!p.lastName?'<small class="legacy-name">Παλαιό ενιαίο όνομα</small>':''}</td><td>${esc(p.firstName)||'—'}</td><td class="mono">${esc(p.amka)||'—'}</td><td>${phone(p.phone)}</td><td>${phone(p.phone2)}</td><td>${p.email?`<a class="directory-contact" href="mailto:${encodeURIComponent(p.email)}">${esc(p.email)}</a>`:'—'}</td><td><div class="row">${button('Στοιχεία','editPatient',p.id,'secondary')}${button('Νέο ραντεβού','followup',p.id,'secondary')}${doctor()?button('Φάκελος','patientSummary',p.id,'secondary'):''}</div></td></tr>`).join('')||'<tr><td colspan="7">Δεν βρέθηκαν ασθενείς.</td></tr>'}</tbody></table></div>`;}
function directoryPage(){const entries=state.patients,withPhone=entries.filter(p=>p.phone||p.phone2).length,withEmail=entries.filter(p=>p.email).length;return `<div class="directory-dashboard"><section class="dashboard-welcome"><div><h2>Οι επαφές των ασθενών σας</h2><p>Γρήγορη επικοινωνία και πρόσβαση στο επόμενο ραντεβού.</p></div>${button('＋ Προσθήκη εικονικού ασθενή','newPatient')}</section><div class="clinic-tiles directory-summary">${[['patients','Καταχωρισμένοι ασθενείς',entries.length,'Στοιχεία από τους υπάρχοντες φακέλους'],['directory','Με διαθέσιμο τηλέφωνο',withPhone,'Κύριο ή δεύτερο τηλέφωνο επικοινωνίας'],['directory','Με διαθέσιμο e-mail',withEmail,'Άνοιγμα προσχεδίου στην εφαρμογή e-mail']].map(([icon,label,count,hint],i)=>`<article class="clinic-tile tile-${i}">${navIcon(icon)}<div><h3>${label}</h3><strong>${count}</strong><p>${hint}</p></div></article>`).join('')}</div><section class="card directory-card"><div class="directory-search-panel"><div class="directory-section-heading">${navIcon('directory')}<div><h2>Κατάλογος επικοινωνίας</h2><p>Εντοπίστε τον σωστό ασθενή πριν από την επικοινωνία ή την καταχώριση ραντεβού.</p></div></div><label for="directorySearch">Αναζήτηση με επίθετο, όνομα, Α.Μ.Κ.Α., τηλέφωνο ή e-mail</label><input id="directorySearch" type="search" value="${esc(directoryQuery)}" placeholder="Αναζήτηση ασθενή…" autocomplete="off"><div class="directory-search-hint"><span>Αλφαβητική ταξινόμηση · Επίθετο → Όνομα</span><span>Κοινά στοιχεία με τον φάκελο ασθενούς</span></div></div><div id="directoryResults" aria-live="polite">${directoryRows()}</div><p class="directory-footer-note">Η κλήση και το e-mail ανοίγουν τη σχετική εφαρμογή της συσκευής. Δεν γίνεται αυτόματη αποστολή.</p></section></div>`;}

function dashboardIntro(title,description){return `<section class="dashboard-welcome unified-intro"><h2>${esc(title)}</h2><p>${esc(description)}</p></section>`;}
function dashboardSummary(items){return `<div class="clinic-tiles unified-summary">${items.map(([icon,label,value,hint],i)=>`<article class="clinic-tile tile-${i}">${navIcon(icon)}<div><h3>${esc(label)}</h3><strong>${esc(value)}</strong><p>${esc(hint)}</p></div></article>`).join('')}</div>`;}
